import React, { useState, useEffect } from 'react';
import {
    Paper,
    Typography,
    Box,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Grid,
    useTheme,
    useMediaQuery,
    Chip,
    Divider,
    CircularProgress,
    Alert,
    Select,
    MenuItem,
    FormControl,
    InputLabel,
    Button,
    ToggleButton,
    ToggleButtonGroup,
    Card,
    CardContent,
    LinearProgress
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import EqualizerIcon from '@mui/icons-material/Equalizer';
import ShowChartIcon from '@mui/icons-material/ShowChart';
import BarChartIcon from '@mui/icons-material/BarChart';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import { ref, get } from "firebase/database";
import { db } from "./firebaseConfig";

const EstadisticasGanancias = () => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [datosEstadisticos, setDatosEstadisticos] = useState({
        gananciasPorAnio: {},
        gananciasPorMes: {},
        crecimientoMensual: [],
        mejorMes: null,
        peorMes: null,
        promedioMensual: 0,
        totalGeneral: 0,
        comparativaAnual: []
    });
    const [anioSeleccionado, setAnioSeleccionado] = useState(new Date().getFullYear());
    const [añosDisponibles, setAñosDisponibles] = useState([]);
    const [tipoVista, setTipoVista] = useState('mensual');

    const meses = [
        'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
        'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
    ];

    // Colores para la paleta
    const colors = {
        violeta: '#7c3aed',
        violetaLight: '#a78bfa',
        naranja: '#ea580c',
        naranjaLight: '#f97316',
        azul: '#3b82f6',
        azulLight: '#60a5fa',
        textoPrincipal: '#1e293b',
        textoSecundario: '#64748b',
        fondo: '#f8fafc',
        blanco: '#ffffff',
        borde: '#e2e8f0'
    };

    const getColorCrecimiento = (crecimiento) => {
        if (crecimiento > 10) return colors.azul;
        if (crecimiento > 0) return colors.violetaLight;
        if (crecimiento === 0) return colors.naranja;
        if (crecimiento > -10) return colors.naranjaLight;
        return '#ef4444';
    };

    const getIconoTendencia = (crecimiento) => {
        if (crecimiento > 0) return <TrendingUpIcon sx={{ color: colors.violeta }} />;
        if (crecimiento === 0) return <EqualizerIcon sx={{ color: colors.naranja }} />;
        return <TrendingDownIcon sx={{ color: '#ef4444' }} />;
    };

    const cargarDatosEstadisticos = async () => {
        setLoading(true);
        setError(null);

        try {
            const pagosRef = ref(db, "pagos");
            const snapshotPagos = await get(pagosRef);
            const casualPaymentsRef = ref(db, "pagosCasuales");
            const snapshotCasual = await get(casualPaymentsRef);

            let todosLosPagos = [];

            if (snapshotPagos.exists()) {
                const pagosData = snapshotPagos.val();
                Object.values(pagosData).forEach(alumnoPagos => {
                    if (alumnoPagos && typeof alumnoPagos === 'object') {
                        Object.values(alumnoPagos).forEach(pago => {
                            if (pago && pago.monto && pago.fechaPago) {
                                todosLosPagos.push({
                                    monto: pago.monto,
                                    fechaPago: pago.fechaPago,
                                    mes: pago.mes || new Date(pago.fechaPago).getMonth() + 1,
                                    anio: pago.anio || new Date(pago.fechaPago).getFullYear(),
                                    tipo: 'alumno'
                                });
                            }
                        });
                    }
                });
            }

            if (snapshotCasual.exists()) {
                const casualData = snapshotCasual.val();
                Object.values(casualData).forEach(pago => {
                    if (pago && pago.monto && pago.fechaPago) {
                        todosLosPagos.push({
                            monto: pago.monto,
                            fechaPago: pago.fechaPago,
                            mes: pago.mes || new Date(pago.fechaPago).getMonth() + 1,
                            anio: pago.anio || new Date(pago.fechaPago).getFullYear(),
                            tipo: 'casual'
                        });
                    }
                });
            }

            const gananciasPorAnio = {};
            const gananciasPorMes = {};
            let totalGeneral = 0;

            todosLosPagos.forEach(pago => {
                const anio = pago.anio;
                const mes = pago.mes;
                const monto = parseFloat(pago.monto);

                totalGeneral += monto;

                if (!gananciasPorAnio[anio]) {
                    gananciasPorAnio[anio] = 0;
                }
                gananciasPorAnio[anio] += monto;

                if (!gananciasPorMes[anio]) {
                    gananciasPorMes[anio] = {};
                }
                if (!gananciasPorMes[anio][mes]) {
                    gananciasPorMes[anio][mes] = 0;
                }
                gananciasPorMes[anio][mes] += monto;
            });

            const crecimientoMensual = [];
            const gananciasAnioActual = gananciasPorMes[anioSeleccionado] || {};

            for (let mes = 1; mes <= 12; mes++) {
                const gananciaActual = gananciasAnioActual[mes] || 0;
                const gananciaAnterior = mes === 1 ? 0 : (gananciasAnioActual[mes - 1] || 0);
                const crecimiento = gananciaAnterior === 0 ? 0 : ((gananciaActual - gananciaAnterior) / gananciaAnterior) * 100;

                crecimientoMensual.push({
                    mes,
                    nombreMes: meses[mes - 1],
                    ganancia: gananciaActual,
                    crecimiento: Math.round(crecimiento * 100) / 100,
                    tendencia: crecimiento > 0 ? 'positiva' : crecimiento < 0 ? 'negativa' : 'estable'
                });
            }

            const mesesConDatos = crecimientoMensual.filter(m => m.ganancia > 0);
            const mejorMes = mesesConDatos.length > 0 ?
                mesesConDatos.reduce((max, m) => m.ganancia > max.ganancia ? m : max, mesesConDatos[0]) : null;
            const peorMes = mesesConDatos.length > 0 ?
                mesesConDatos.reduce((min, m) => m.ganancia < min.ganancia ? m : min, mesesConDatos[0]) : null;

            const mesesConGanancias = crecimientoMensual.filter(m => m.ganancia > 0).length;
            const promedioMensual = mesesConGanancias > 0 ?
                crecimientoMensual.reduce((sum, m) => sum + m.ganancia, 0) / mesesConGanancias : 0;

            const añosOrdenados = Object.keys(gananciasPorAnio).sort();
            setAñosDisponibles(añosOrdenados);

            const comparativaAnual = añosOrdenados.map(anio => ({
                anio,
                total: gananciasPorAnio[anio],
                crecimiento: 0
            }));

            for (let i = 1; i < comparativaAnual.length; i++) {
                const anterior = comparativaAnual[i - 1].total;
                const actual = comparativaAnual[i].total;
                comparativaAnual[i].crecimiento = anterior === 0 ? 0 : ((actual - anterior) / anterior) * 100;
            }

            setDatosEstadisticos({
                gananciasPorAnio,
                gananciasPorMes,
                crecimientoMensual,
                mejorMes,
                peorMes,
                promedioMensual: Math.round(promedioMensual),
                totalGeneral,
                comparativaAnual
            });

        } catch (err) {
            console.error("Error al cargar datos estadísticos:", err);
            setError("Error al cargar los datos estadísticos");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        cargarDatosEstadisticos();
    }, [anioSeleccionado]);

    const handleCambiarAnio = (event) => {
        setAnioSeleccionado(event.target.value);
    };

    const handleCambiarVista = (event, nuevaVista) => {
        if (nuevaVista !== null) {
            setTipoVista(nuevaVista);
        }
    };

    const formatearMoneda = (monto) => {
        return new Intl.NumberFormat('es-AR', {
            style: 'currency',
            currency: 'ARS',
            minimumFractionDigits: 0,
            maximumFractionDigits: 0
        }).format(monto);
    };

    const calcularProgreso = (ganancia) => {
        const maxGanancia = Math.max(...datosEstadisticos.crecimientoMensual.map(m => m.ganancia), 1);
        return (ganancia / maxGanancia) * 100;
    };

    if (loading) {
        return (
            <Paper sx={{ p: 3, backgroundColor: colors.blanco, borderRadius: 2, mt: 3, boxShadow: '0 1px 3px rgba(0,0,0,0.05)' }}>
                <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', flexDirection: 'column', gap: 2 }}>
                    <CircularProgress sx={{ color: colors.violeta }} />
                    <Typography sx={{ color: colors.textoSecundario }}>Cargando estadísticas...</Typography>
                </Box>
            </Paper>
        );
    }

    if (error) {
        return (
            <Paper sx={{ p: 3, backgroundColor: colors.blanco, borderRadius: 2, mt: 3 }}>
                <Alert severity="error">{error}</Alert>
            </Paper>
        );
    }

    return (
        <Paper elevation={0} sx={{ mt: 3, borderRadius: 2, backgroundColor: colors.blanco, overflow: 'hidden', border: `1px solid ${colors.borde}` }}>
            <Accordion defaultExpanded sx={{ backgroundColor: 'transparent', boxShadow: 'none' }}>
                <AccordionSummary expandIcon={<ExpandMoreIcon sx={{ color: colors.textoPrincipal }} />}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%', flexWrap: 'wrap' }}>
                        <ShowChartIcon sx={{ color: colors.violeta }} />
                        <Typography variant={isMobile ? "h6" : "h5"} sx={{ color: colors.violeta, fontWeight: 'bold' }}>
                            Estadísticas de Ganancias
                        </Typography>
                        <Chip
                            label={`Total: ${formatearMoneda(datosEstadisticos.totalGeneral)}`}
                            size="small"
                            sx={{ backgroundColor: colors.azul, color: colors.blanco }}
                        />
                    </Box>
                </AccordionSummary>

                <AccordionDetails>
                    <Box sx={{ mb: 3 }}>
                        <ToggleButtonGroup
                            value={tipoVista}
                            exclusive
                            onChange={handleCambiarVista}
                            sx={{ mb: 2, width: '100%', justifyContent: 'center' }}
                        >
                            <ToggleButton value="mensual" sx={{ borderRadius: 4, color: colors.textoSecundario, '&.Mui-selected': { backgroundColor: colors.violeta, color: colors.blanco } }}>
                                {isMobile ? <BarChartIcon /> : 'Mensual'}
                            </ToggleButton>
                            <ToggleButton value="anual" sx={{ color: colors.textoSecundario, '&.Mui-selected': { backgroundColor: colors.violeta, color: colors.blanco } }}>
                                {isMobile ? <EqualizerIcon /> : 'Anual'}
                            </ToggleButton>
                            <ToggleButton value="comparativa" sx={{ borderRadius: 4, color: colors.textoSecundario, '&.Mui-selected': { backgroundColor: colors.violeta, color: colors.blanco } }}>
                                {isMobile ? <TrendingUpIcon /> : 'Comparativa'}
                            </ToggleButton>
                        </ToggleButtonGroup>
                    </Box>

                    {tipoVista === 'mensual' && (
                        <>
                            <Box sx={{ mb: 3, display: 'flex', justifyContent: 'center' }}>
                                <FormControl size="small" sx={{ minWidth: 120 }}>
                                    <InputLabel sx={{ color: colors.textoSecundario }}>Año</InputLabel>
                                    <Select
                                        value={anioSeleccionado}
                                        onChange={handleCambiarAnio}
                                        label="Año"
                                        sx={{ color: colors.textoPrincipal, '& .MuiOutlinedInput-notchedOutline': { borderColor: colors.borde } }}
                                    >
                                        {añosDisponibles.map(anio => (
                                            <MenuItem key={anio} value={anio}>{anio}</MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </Box>

                            <Grid container spacing={2} sx={{ mb: 3 }}>
                                <Grid item xs={12} sm={4}>
                                    <Card sx={{ backgroundColor: colors.fondo, height: '100%', border: `1px solid ${colors.borde}` }}>
                                        <CardContent>
                                            <Typography variant="body2" sx={{ color: colors.textoSecundario }}>Total {anioSeleccionado}</Typography>
                                            <Typography variant="h5" sx={{ color: colors.violeta, fontWeight: 'bold' }}>
                                                {formatearMoneda(datosEstadisticos.gananciasPorAnio[anioSeleccionado] || 0)}
                                            </Typography>
                                        </CardContent>
                                    </Card>
                                </Grid>
                                <Grid item xs={12} sm={4}>
                                    <Card sx={{ backgroundColor: colors.fondo, height: '100%', border: `1px solid ${colors.borde}` }}>
                                        <CardContent>
                                            <Typography variant="body2" sx={{ color: colors.textoSecundario }}>Promedio Mensual</Typography>
                                            <Typography variant="h5" sx={{ color: colors.azul, fontWeight: 'bold' }}>
                                                {formatearMoneda(datosEstadisticos.promedioMensual)}
                                            </Typography>
                                        </CardContent>
                                    </Card>
                                </Grid>
                                <Grid item xs={12} sm={4}>
                                    <Card sx={{ backgroundColor: colors.fondo, height: '100%', border: `1px solid ${colors.borde}` }}>
                                        <CardContent>
                                            <Typography variant="body2" sx={{ color: colors.textoSecundario }}>Mejor Mes</Typography>
                                            <Typography variant="h5" sx={{ color: colors.naranja, fontWeight: 'bold' }}>
                                                {datosEstadisticos.mejorMes ? `${datosEstadisticos.mejorMes.nombreMes}` : 'N/A'}
                                            </Typography>
                                            {datosEstadisticos.mejorMes && (
                                                <Typography variant="caption" sx={{ color: colors.azul }}>
                                                    {formatearMoneda(datosEstadisticos.mejorMes.ganancia)}
                                                </Typography>
                                            )}
                                        </CardContent>
                                    </Card>
                                </Grid>
                            </Grid>

                            <Typography variant="h6" sx={{ color: colors.textoPrincipal, mb: 2 }}>
                                Ganancias Mensuales - {anioSeleccionado}
                            </Typography>

                            <Box sx={{ maxHeight: 400, overflow: 'auto' }}>
                                {datosEstadisticos.crecimientoMensual.map((item) => (
                                    <Box key={item.mes} sx={{ mb: 2 }}>
                                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 0.5 }}>
                                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                <Typography variant="body2" sx={{ color: colors.textoPrincipal, fontWeight: 'bold', minWidth: 80 }}>
                                                    {item.nombreMes}
                                                </Typography>
                                                {item.ganancia > 0 && (
                                                    <Chip
                                                        label={formatearMoneda(item.ganancia)}
                                                        size="small"
                                                        sx={{ backgroundColor: colors.violetaLight, color: colors.blanco, height: 20, fontSize: '10px' }}
                                                    />
                                                )}
                                            </Box>
                                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                {getIconoTendencia(item.crecimiento)}
                                                <Typography
                                                    variant="caption"
                                                    sx={{ color: getColorCrecimiento(item.crecimiento), fontWeight: 'bold' }}
                                                >
                                                    {item.crecimiento > 0 ? '+' : ''}{item.crecimiento}%
                                                </Typography>
                                            </Box>
                                        </Box>
                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                            <LinearProgress
                                                variant="determinate"
                                                value={calcularProgreso(item.ganancia)}
                                                sx={{
                                                    flex: 1,
                                                    height: 8,
                                                    borderRadius: 4,
                                                    backgroundColor: colors.borde,
                                                    '& .MuiLinearProgress-bar': {
                                                        backgroundColor: item.ganancia > 0 ? colors.azul : '#ef4444',
                                                        borderRadius: 4
                                                    }
                                                }}
                                            />
                                            <Typography variant="caption" sx={{ color: colors.textoSecundario, minWidth: 60 }}>
                                                {item.crecimiento > 0 ? '↑' : item.crecimiento < 0 ? '↓' : '→'} {Math.abs(item.crecimiento)}%
                                            </Typography>
                                        </Box>
                                    </Box>
                                ))}
                            </Box>
                        </>
                    )}

                    {tipoVista === 'anual' && (
                        <>
                            <Typography variant="h6" sx={{ color: colors.textoPrincipal, mb: 2 }}>
                                Resumen por Año
                            </Typography>

                            <Grid container spacing={2}>
                                {datosEstadisticos.comparativaAnual.map((item, index) => (
                                    <Grid item xs={12} sm={6} md={4} key={item.anio}>
                                        <Card sx={{ backgroundColor: colors.fondo, border: `1px solid ${colors.borde}` }}>
                                            <CardContent>
                                                <Typography variant="h6" sx={{ color: colors.violeta, fontWeight: 'bold' }}>
                                                    {item.anio}
                                                </Typography>
                                                <Typography variant="h5" sx={{ color: colors.textoPrincipal, fontWeight: 'bold' }}>
                                                    {formatearMoneda(item.total)}
                                                </Typography>
                                                {index > 0 && (
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1 }}>
                                                        {getIconoTendencia(item.crecimiento)}
                                                        <Typography
                                                            variant="body2"
                                                            sx={{ color: getColorCrecimiento(item.crecimiento), fontWeight: 'bold' }}
                                                        >
                                                            {item.crecimiento > 0 ? '+' : ''}{item.crecimiento.toFixed(1)}% vs {datosEstadisticos.comparativaAnual[index - 1].anio}
                                                        </Typography>
                                                    </Box>
                                                )}
                                            </CardContent>
                                        </Card>
                                    </Grid>
                                ))}
                            </Grid>

                            {datosEstadisticos.comparativaAnual.length > 0 && (
                                <Box sx={{ mt: 3 }}>
                                    <Divider sx={{ my: 2, borderColor: colors.borde }} />
                                    <Typography variant="subtitle1" sx={{ color: colors.textoPrincipal, mb: 2 }}>
                                        Datos Destacados
                                    </Typography>
                                    <Grid container spacing={2}>
                                        <Grid item xs={12} sm={6}>
                                            <Card sx={{ backgroundColor: colors.fondo, borderLeft: `4px solid ${colors.azul}`, border: `1px solid ${colors.borde}` }}>
                                                <CardContent>
                                                    <Typography variant="body2" sx={{ color: colors.textoSecundario }}>
                                                        Mejor Año
                                                    </Typography>
                                                    <Typography variant="h6" sx={{ color: colors.azul, fontWeight: 'bold' }}>
                                                        {datosEstadisticos.comparativaAnual.reduce((max, item) =>
                                                            item.total > max.total ? item : max,
                                                            datosEstadisticos.comparativaAnual[0]
                                                        ).anio}
                                                    </Typography>
                                                </CardContent>
                                            </Card>
                                        </Grid>
                                        <Grid item xs={12} sm={6}>
                                            <Card sx={{ backgroundColor: colors.fondo, borderLeft: `4px solid ${colors.naranja}`, border: `1px solid ${colors.borde}` }}>
                                                <CardContent>
                                                    <Typography variant="body2" sx={{ color: colors.textoSecundario }}>
                                                        Crecimiento Total
                                                    </Typography>
                                                    <Typography variant="h6" sx={{ color: colors.violeta, fontWeight: 'bold' }}>
                                                        {datosEstadisticos.comparativaAnual.length > 1 ?
                                                            `${(datosEstadisticos.comparativaAnual[datosEstadisticos.comparativaAnual.length - 1].crecimiento).toFixed(1)}%` :
                                                            '0%'
                                                        }
                                                    </Typography>
                                                </CardContent>
                                            </Card>
                                        </Grid>
                                    </Grid>
                                </Box>
                            )}
                        </>
                    )}

                    {tipoVista === 'comparativa' && (
                        <>
                            <Typography variant="h6" sx={{ color: colors.textoPrincipal, mb: 2 }}>
                                Comparativa de Ganancias por Mes
                            </Typography>
                            <Typography variant="caption" sx={{ color: colors.textoSecundario, display: 'block', mb: 2 }}>
                                Comparación entre el año actual y el año anterior
                            </Typography>

                            {añosDisponibles.length >= 2 ? (
                                (() => {
                                    const anioActual = parseInt(anioSeleccionado);
                                    const anioAnterior = anioActual - 1;
                                    const datosActual = datosEstadisticos.gananciasPorMes[anioActual] || {};
                                    const datosAnterior = datosEstadisticos.gananciasPorMes[anioAnterior] || {};

                                    return (
                                        <Box sx={{ maxHeight: 400, overflow: 'auto' }}>
                                            {meses.map((mes, idx) => {
                                                const mesNum = idx + 1;
                                                const gananciaActual = datosActual[mesNum] || 0;
                                                const gananciaAnterior = datosAnterior[mesNum] || 0;
                                                const diferencia = gananciaActual - gananciaAnterior;
                                                const porcentaje = gananciaAnterior === 0 ?
                                                    (gananciaActual > 0 ? 100 : 0) :
                                                    ((diferencia / gananciaAnterior) * 100);

                                                return (
                                                    <Box key={mes} sx={{ mb: 3 }}>
                                                        <Typography variant="subtitle2" sx={{ color: colors.violeta, mb: 1 }}>
                                                            {mes}
                                                        </Typography>
                                                        <Grid container spacing={2}>
                                                            <Grid item xs={6}>
                                                                <Box sx={{ textAlign: 'center' }}>
                                                                    <Typography variant="caption" sx={{ color: colors.textoSecundario }}>
                                                                        {anioAnterior}
                                                                    </Typography>
                                                                    <Typography variant="body2" sx={{ color: colors.naranja }}>
                                                                        {formatearMoneda(gananciaAnterior)}
                                                                    </Typography>
                                                                </Box>
                                                            </Grid>
                                                            <Grid item xs={6}>
                                                                <Box sx={{ textAlign: 'center' }}>
                                                                    <Typography variant="caption" sx={{ color: colors.textoSecundario }}>
                                                                        {anioActual}
                                                                    </Typography>
                                                                    <Typography variant="body2" sx={{ color: gananciaActual > gananciaAnterior ? colors.azul : '#ef4444' }}>
                                                                        {formatearMoneda(gananciaActual)}
                                                                    </Typography>
                                                                </Box>
                                                            </Grid>
                                                        </Grid>
                                                        {gananciaActual > 0 || gananciaAnterior > 0 ? (
                                                            <Box sx={{ mt: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1 }}>
                                                                {getIconoTendencia(porcentaje)}
                                                                <Typography variant="caption" sx={{ color: getColorCrecimiento(porcentaje) }}>
                                                                    {porcentaje > 0 ? '+' : ''}{porcentaje.toFixed(1)}%
                                                                </Typography>
                                                            </Box>
                                                        ) : null}
                                                        <Divider sx={{ mt: 2, borderColor: colors.borde }} />
                                                    </Box>
                                                );
                                            })}
                                        </Box>
                                    );
                                })()
                            ) : (
                                <Alert severity="info" sx={{ backgroundColor: colors.fondo, color: colors.textoPrincipal }}>
                                    Se necesitan al menos 2 años de datos para mostrar la comparativa
                                </Alert>
                            )}
                        </>
                    )}

                    <Divider sx={{ my: 3, borderColor: colors.borde }} />
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 1 }}>
                        <Chip
                            icon={<AttachMoneyIcon />}
                            label={`Total de pagos procesados: ${datosEstadisticos.totalGeneral > 0 ? '✓' : 'Sin datos'}`}
                            size="small"
                            sx={{ backgroundColor: colors.azul, color: colors.blanco }}
                        />
                        <Chip
                            icon={<CalendarTodayIcon />}
                            label={`Datos desde ${añosDisponibles[0] || 'N/A'} hasta ${añosDisponibles[añosDisponibles.length - 1] || 'N/A'}`}
                            size="small"
                            sx={{ backgroundColor: colors.violeta, color: colors.blanco }}
                        />
                    </Box>
                </AccordionDetails>
            </Accordion>
        </Paper>
    );
};

export default EstadisticasGanancias;