import React, { useState, useEffect } from "react";
import {
    Box,
    Typography,
    Button,
    TextField,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    IconButton,
    Chip,
    Grid,
    Card,
    CardContent,
    useMediaQuery,
    useTheme,
    Divider
} from "@mui/material";
import { useNavigate } from "react-router-dom";
import { ref, get, push, set } from "firebase/database";
import { db } from "./firebaseConfig";
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import ExpandLessIcon from '@mui/icons-material/ExpandLess';
import ShoppingCartIcon from '@mui/icons-material/ShoppingCart';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import PeopleIcon from '@mui/icons-material/People';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import { useThemeContext } from './ThemeContext';

const VentaVarios = () => {
    const navigate = useNavigate();
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const { actualTheme } = useThemeContext();

    const [cliente, setCliente] = useState("");
    const [ventas, setVentas] = useState([]);
    const [nuevoProducto, setNuevoProducto] = useState({ nombre: "", precio: "", cantidad: "" });
    const [productosSeleccionados, setProductosSeleccionados] = useState([]);
    const [openDialog, setOpenDialog] = useState(false);
    const [totalGananciasAlumnos, setTotalGananciasAlumnos] = useState(0);
    const [historialGanancias, setHistorialGanancias] = useState([]);
    const [showHistorial, setShowHistorial] = useState(false);
    const [pagosAlumnos, setPagosAlumnos] = useState([]);

    const colors = {
        violeta: '#7c3aed',
        violetaLight: '#a78bfa',
        naranja: '#ea580c',
        naranjaLight: '#f97316',
        azul: '#3b82f6',
        azulLight: '#60a5fa',
        textoPrincipal: '#1e293b',
        textoSecundario: '#64748b',
        fondo: '#f8fafc',
        blanco: '#ffffff',
        borde: '#e2e8f0',
        exito: '#10b981',
        error: '#ef4444'
    };

    useEffect(() => {
        const cargarDatos = async () => {
            await Promise.all([
                cargarVentasDelMes(),
                cargarGananciasAlumnos(),
                cargarHistorialGanancias()
            ]);
        };
        cargarDatos();
    }, []);

    const cargarVentasDelMes = async () => {
        try {
            const ventasRef = ref(db, "ventas");
            const snapshot = await get(ventasRef);
            if (snapshot.exists()) {
                const data = snapshot.val();
                const mesActual = new Date().getMonth() + 1;
                const anioActual = new Date().getFullYear();

                const ventasFiltradas = Object.values(data).filter(
                    (venta) => {
                        const fechaVenta = new Date(venta.fecha);
                        return fechaVenta.getMonth() + 1 === mesActual &&
                            fechaVenta.getFullYear() === anioActual;
                    }
                );
                setVentas(ventasFiltradas);
            }
        } catch (error) {
            console.error("Error al cargar las ventas:", error);
        }
    };

    const cargarGananciasAlumnos = async () => {
        try {
            const pagosRef = ref(db, "pagos");
            const alumnosRef = ref(db, "alumnos");

            const [pagosSnapshot, alumnosSnapshot] = await Promise.all([
                get(pagosRef),
                get(alumnosRef)
            ]);

            if (!pagosSnapshot.exists()) {
                setPagosAlumnos([]);
                setTotalGananciasAlumnos(0);
                return;
            }

            const pagosData = pagosSnapshot.val();
            const alumnosData = alumnosSnapshot.exists() ? alumnosSnapshot.val() : {};
            const mesActual = new Date().getMonth() + 1;
            const anioActual = new Date().getFullYear();

            let total = 0;
            let pagosMesActual = [];

            Object.entries(pagosData).forEach(([alumnoId, pagos]) => {
                const alumno = alumnosData[alumnoId] || {};
                const nombreAlumno = alumno.nombre
                    ? `${alumno.nombre} ${alumno.apellido || ''}`.trim()
                    : `Alumno ${alumnoId}`;

                if (pagos && typeof pagos === 'object') {
                    Object.entries(pagos).forEach(([pagoId, pago]) => {
                        try {
                            if (pago && pago.monto && pago.fechaPago) {
                                let fechaPago;
                                if (typeof pago.fechaPago === 'string') {
                                    if (pago.fechaPago.includes('T')) {
                                        fechaPago = new Date(pago.fechaPago);
                                    } else {
                                        fechaPago = new Date(pago.fechaPago + 'T00:00:00');
                                    }
                                } else if (pago.fechaPago instanceof Date) {
                                    fechaPago = pago.fechaPago;
                                } else {
                                    return;
                                }

                                if (isNaN(fechaPago.getTime())) return;

                                if (fechaPago.getMonth() + 1 === mesActual &&
                                    fechaPago.getFullYear() === anioActual) {

                                    total += Number(pago.monto);
                                    pagosMesActual.push({
                                        id: pagoId,
                                        alumnoId,
                                        alumno: nombreAlumno,
                                        monto: Number(pago.monto),
                                        fecha: pago.fechaPago,
                                        fechaObj: fechaPago,
                                        descripcion: pago.descripcion || "Pago de clases"
                                    });
                                }
                            }
                        } catch (error) {
                            console.error(`Error procesando pago ${pagoId}:`, error);
                        }
                    });
                }
            });

            pagosMesActual.sort((a, b) => b.fechaObj - a.fechaObj);
            setTotalGananciasAlumnos(total);
            setPagosAlumnos(pagosMesActual);

        } catch (error) {
            console.error("Error al cargar las ganancias de alumnos:", error);
        }
    };

    const cargarHistorialGanancias = async () => {
        try {
            const [ventasSnapshot, pagosSnapshot, alumnosSnapshot] = await Promise.all([
                get(ref(db, "ventas")),
                get(ref(db, "pagos")),
                get(ref(db, "alumnos"))
            ]);

            const historial = {};
            const alumnosData = alumnosSnapshot.exists() ? alumnosSnapshot.val() : {};

            if (ventasSnapshot.exists()) {
                Object.values(ventasSnapshot.val()).forEach(venta => {
                    const fecha = new Date(venta.fecha);
                    const mes = fecha.getMonth() + 1;
                    const anio = fecha.getFullYear();
                    const key = `${anio}-${mes}`;

                    if (!historial[key]) {
                        historial[key] = {
                            mes,
                            anio,
                            totalVentas: 0,
                            totalClases: 0,
                            detallesClases: []
                        };
                    }
                    historial[key].totalVentas += venta.total;
                });
            }

            if (pagosSnapshot.exists()) {
                Object.entries(pagosSnapshot.val()).forEach(([alumnoId, pagosAlumno]) => {
                    const alumno = alumnosData[alumnoId] || {};
                    const nombreAlumno = alumno.nombre
                        ? `${alumno.nombre} ${alumno.apellido || ''}`.trim()
                        : `Alumno ${alumnoId}`;

                    Object.entries(pagosAlumno).forEach(([pagoId, pago]) => {
                        if (typeof pago === 'object' && pago.monto) {
                            const fecha = new Date(pago.fechaPago);
                            const mes = fecha.getMonth() + 1;
                            const anio = fecha.getFullYear();
                            const key = `${anio}-${mes}`;

                            if (!historial[key]) {
                                historial[key] = {
                                    mes,
                                    anio,
                                    totalVentas: 0,
                                    totalClases: 0,
                                    detallesClases: []
                                };
                            }

                            historial[key].totalClases += pago.monto;
                            historial[key].detallesClases.push({
                                alumno: nombreAlumno,
                                monto: pago.monto,
                                fecha: pago.fechaPago,
                                descripcion: pago.descripcion || "Pago de clases"
                            });
                        }
                    });
                });
            }

            const historialArray = Object.values(historial).sort((a, b) => {
                if (a.anio !== b.anio) return b.anio - a.anio;
                return b.mes - a.mes;
            });

            setHistorialGanancias(historialArray);
        } catch (error) {
            console.error("Error al cargar el historial de ganancias:", error);
        }
    };

    const handleAgregarProducto = () => {
        if (!nuevoProducto.nombre || !nuevoProducto.precio || !nuevoProducto.cantidad) {
            alert("Ingresa nombre, precio y cantidad del producto.");
            return;
        }
        setProductosSeleccionados((prev) => [...prev, { ...nuevoProducto }]);
        setNuevoProducto({ nombre: "", precio: "", cantidad: "" });
        setOpenDialog(false);
    };

    const handleVentaSubmit = async () => {
        if (!cliente.trim()) {
            alert("Ingresa el nombre del cliente.");
            return;
        }
        if (productosSeleccionados.length === 0) {
            alert("Agrega al menos un producto a la venta.");
            return;
        }
        const totalVenta = productosSeleccionados.reduce(
            (total, producto) => total + (parseFloat(producto.precio) * parseInt(producto.cantidad)),
            0
        );

        try {
            const ventasRef = ref(db, "ventas");
            const nuevaVenta = push(ventasRef);
            await set(nuevaVenta, {
                cliente,
                productos: productosSeleccionados,
                fecha: new Date().toISOString(),
                descripcion: `Venta a ${cliente} con ${productosSeleccionados.length} productos. Total: $${totalVenta}`,
                total: totalVenta
            });
            setCliente("");
            setProductosSeleccionados([]);
            cargarVentasDelMes();
            cargarHistorialGanancias();
        } catch (error) {
            console.error("Error al registrar la venta:", error);
        }
    };

    const totalVentasMes = ventas.reduce((total, venta) => total + venta.total, 0);

    const obtenerNombreMes = (mes) => {
        const meses = [
            "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
            "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
        ];
        return meses[mes - 1] || mes;
    };

    const formatearMoneda = (monto) => {
        return new Intl.NumberFormat('es-AR', {
            style: 'currency',
            currency: 'ARS',
            minimumFractionDigits: 0,
            maximumFractionDigits: 0
        }).format(monto);
    };

    return (
        <Box sx={{
            padding: isMobile ? 1 : 2,
            backgroundColor: colors.fondo,
            borderRadius: 2,
            minHeight: '100vh'
        }}>
            {/* Título */}
            <Typography
                variant="h5"
                textAlign="start"
                gutterBottom
                sx={{
                    color: colors.violeta,
                    fontWeight: 'bold',
                    mb: 3
                }}
            >
                🛒 Venta de Productos
            </Typography>

            {/* Campo Cliente */}
            <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
                <TextField
                    sx={{
                        width: isMobile ? '100%' : '50%',
                        '& .MuiOutlinedInput-root': {
                            borderRadius: '40px',
                            backgroundColor: colors.blanco,
                            '& fieldset': { borderColor: colors.borde },
                            '&:hover fieldset': { borderColor: colors.violeta },
                            '&.Mui-focused fieldset': { borderColor: colors.violeta }
                        },
                        '& .MuiInputLabel-root': { color: colors.textoSecundario },
                        '& .MuiInputLabel-root.Mui-focused': { color: colors.violeta }
                    }}
                    label="Nombre del Cliente"
                    value={cliente}
                    onChange={(e) => setCliente(e.target.value)}
                    margin="normal"
                    size={isMobile ? "small" : "medium"}
                />
            </Box>

            {/* Productos Seleccionados */}
            <Paper sx={{ p: 2, mb: 2, backgroundColor: colors.blanco, border: `1px solid ${colors.borde}` }}>
                <Typography variant="h6" sx={{ color: colors.textoPrincipal, mb: 1 }}>
                    📦 Productos Seleccionados:
                </Typography>
                {productosSeleccionados.length === 0 ? (
                    <Typography variant="body2" sx={{ color: colors.textoSecundario }}>
                        No hay productos seleccionados
                    </Typography>
                ) : (
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                        {productosSeleccionados.map((producto, index) => (
                            <Chip
                                key={index}
                                label={`${producto.nombre} - $${producto.precio} x ${producto.cantidad}`}
                                sx={{
                                    backgroundColor: colors.violetaLight,
                                    color: colors.blanco,
                                    fontWeight: 500
                                }}
                            />
                        ))}
                    </Box>
                )}
            </Paper>

            {/* Botones de acción */}
            <Box sx={{ display: 'flex', justifyContent: 'center', gap: 2, flexWrap: 'wrap', mb: 2 }}>
                <Button
                    variant="contained"
                    sx={{
                        borderRadius: '40px',
                        backgroundColor: colors.violeta,
                        textTransform: 'none',
                        fontWeight: 600,
                        '&:hover': {
                            backgroundColor: colors.violeta,
                            opacity: 0.9,
                            transform: 'scale(1.02)'
                        }
                    }}
                    onClick={() => setOpenDialog(true)}
                >
                    <ShoppingCartIcon sx={{ mr: 1 }} />
                    Agregar Producto
                </Button>

                <Button
                    variant="contained"
                    sx={{
                        borderRadius: '40px',
                        backgroundColor: colors.exito,
                        textTransform: 'none',
                        fontWeight: 600,
                        '&:hover': {
                            backgroundColor: colors.exito,
                            opacity: 0.9,
                            transform: 'scale(1.02)'
                        }
                    }}
                    onClick={handleVentaSubmit}
                >
                    <AttachMoneyIcon sx={{ mr: 1 }} />
                    Confirmar Venta
                </Button>
            </Box>

            {/* Dialog Agregar Producto */}
            <Dialog
                open={openDialog}
                onClose={() => setOpenDialog(false)}
                PaperProps={{
                    sx: {
                        borderRadius: 3,
                        backgroundColor: colors.blanco,
                        padding: 1
                    }
                }}
            >
                <DialogTitle sx={{ color: colors.violeta, fontWeight: 'bold' }}>
                    Agregar Producto
                </DialogTitle>
                <DialogContent>
                    <TextField
                        label="Nombre"
                        fullWidth
                        value={nuevoProducto.nombre}
                        onChange={(e) => setNuevoProducto({ ...nuevoProducto, nombre: e.target.value })}
                        margin="normal"
                        size="small"
                        sx={{
                            '& .MuiOutlinedInput-root': {
                                '& fieldset': { borderColor: colors.borde },
                                '&:hover fieldset': { borderColor: colors.violeta },
                                '&.Mui-focused fieldset': { borderColor: colors.violeta }
                            }
                        }}
                    />
                    <TextField
                        label="Precio"
                        fullWidth
                        type="number"
                        value={nuevoProducto.precio}
                        onChange={(e) => setNuevoProducto({ ...nuevoProducto, precio: e.target.value })}
                        margin="normal"
                        size="small"
                        sx={{
                            '& .MuiOutlinedInput-root': {
                                '& fieldset': { borderColor: colors.borde },
                                '&:hover fieldset': { borderColor: colors.violeta },
                                '&.Mui-focused fieldset': { borderColor: colors.violeta }
                            }
                        }}
                    />
                    <TextField
                        label="Cantidad"
                        fullWidth
                        type="number"
                        value={nuevoProducto.cantidad}
                        onChange={(e) => setNuevoProducto({ ...nuevoProducto, cantidad: e.target.value })}
                        margin="normal"
                        size="small"
                        sx={{
                            '& .MuiOutlinedInput-root': {
                                '& fieldset': { borderColor: colors.borde },
                                '&:hover fieldset': { borderColor: colors.violeta },
                                '&.Mui-focused fieldset': { borderColor: colors.violeta }
                            }
                        }}
                    />
                </DialogContent>
                <DialogActions sx={{ px: 3, pb: 2 }}>
                    <Button onClick={() => setOpenDialog(false)} sx={{ color: colors.textoSecundario }}>
                        Cancelar
                    </Button>
                    <Button
                        onClick={handleAgregarProducto}
                        variant="contained"
                        sx={{
                            borderRadius: '40px',
                            backgroundColor: colors.violeta,
                            '&:hover': { backgroundColor: colors.violeta, opacity: 0.9 }
                        }}
                    >
                        Agregar
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Ventas del Mes */}
            <Paper sx={{ p: 2, mb: 3, backgroundColor: colors.blanco, border: `1px solid ${colors.borde}` }}>
                <Typography variant="h6" sx={{ color: colors.textoPrincipal, mb: 2 }}>
                    📋 Ventas del Mes
                </Typography>
                {ventas.length === 0 ? (
                    <Typography textAlign='center' sx={{ color: colors.textoSecundario }}>
                        Todavía no hay ventas.
                    </Typography>
                ) : (
                    ventas.map((venta, index) => (
                        <Box
                            key={index}
                            sx={{
                                p: 2,
                                mb: 1,
                                border: `1px solid ${colors.borde}`,
                                borderRadius: 2,
                                backgroundColor: colors.fondo
                            }}
                        >
                            <Typography sx={{ color: colors.textoPrincipal }}>
                                {venta.descripcion} - Total: <strong style={{ color: colors.violeta }}>${venta.total}</strong>
                            </Typography>
                            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 1 }}>
                                {venta.productos.map((producto, idx) => (
                                    <Chip
                                        key={idx}
                                        label={`${producto.nombre} - $${producto.precio} x ${producto.cantidad}`}
                                        size="small"
                                        sx={{ backgroundColor: colors.borde, color: colors.textoSecundario }}
                                    />
                                ))}
                            </Box>
                        </Box>
                    ))
                )}
            </Paper>

            {/* Pagos de Alumnos */}
            <Paper sx={{ p: 2, mb: 3, backgroundColor: colors.blanco, border: `1px solid ${colors.borde}` }}>
                <Typography variant="h6" sx={{ color: colors.textoPrincipal, mb: 2 }}>
                    👥 Pagos de Alumnos del Mes
                </Typography>
                {pagosAlumnos.length === 0 ? (
                    <Typography textAlign='center' sx={{ color: colors.textoSecundario }}>
                        No se encontraron pagos de alumnos este mes.
                    </Typography>
                ) : (
                    <TableContainer>
                        <Table size={isMobile ? "small" : "medium"}>
                            <TableHead>
                                <TableRow sx={{ backgroundColor: colors.fondo }}>
                                    <TableCell sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>Alumno</TableCell>
                                    <TableCell align="right" sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>Monto</TableCell>
                                    <TableCell sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>Fecha</TableCell>
                                    <TableCell sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>Descripción</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {pagosAlumnos.map((pago) => (
                                    <TableRow key={`${pago.alumnoId}-${pago.id}`}>
                                        <TableCell sx={{ color: colors.textoPrincipal }}>{pago.alumno}</TableCell>
                                        <TableCell align="right" sx={{ color: colors.violeta, fontWeight: 'bold' }}>
                                            {formatearMoneda(pago.monto)}
                                        </TableCell>
                                        <TableCell sx={{ color: colors.textoSecundario }}>{pago.fecha}</TableCell>
                                        <TableCell sx={{ color: colors.textoSecundario }}>{pago.descripcion}</TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                )}
            </Paper>

            {/* Totales */}
            <Grid container spacing={2} sx={{ mb: 3 }}>
                <Grid item xs={12} sm={4}>
                    <Card sx={{ backgroundColor: colors.fondo, border: `1px solid ${colors.borde}` }}>
                        <CardContent>
                            <Typography variant="body2" sx={{ color: colors.textoSecundario }}>
                                Total Ventas
                            </Typography>
                            <Typography variant="h5" sx={{ color: colors.azul, fontWeight: 'bold' }}>
                                {formatearMoneda(totalVentasMes)}
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} sm={4}>
                    <Card sx={{ backgroundColor: colors.fondo, border: `1px solid ${colors.borde}` }}>
                        <CardContent>
                            <Typography variant="body2" sx={{ color: colors.textoSecundario }}>
                                Total Pagos Alumnos
                            </Typography>
                            <Typography variant="h5" sx={{ color: colors.naranja, fontWeight: 'bold' }}>
                                {formatearMoneda(totalGananciasAlumnos)}
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} sm={4}>
                    <Card sx={{
                        backgroundColor: colors.violeta,
                        border: `1px solid ${colors.violeta}`,
                        background: `linear-gradient(135deg, ${colors.violeta} 0%, ${colors.violetaLight} 100%)`
                    }}>
                        <CardContent>
                            <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.8)' }}>
                                Ganancia Total
                            </Typography>
                            <Typography variant="h5" sx={{ color: colors.blanco, fontWeight: 'bold' }}>
                                {formatearMoneda(totalVentasMes + totalGananciasAlumnos)}
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            {/* Historial de Ganancias */}
            <Accordion
                expanded={showHistorial}
                onChange={() => setShowHistorial(!showHistorial)}
                sx={{
                    mb: 3,
                    backgroundColor: colors.blanco,
                    border: `1px solid ${colors.borde}`,
                    borderRadius: 2,
                    '&:before': { display: 'none' }
                }}
            >
                <AccordionSummary
                    expandIcon={<ExpandMoreIcon sx={{ color: colors.violeta }} />}
                    sx={{
                        backgroundColor: colors.fondo,
                        borderRadius: showHistorial ? '8px 8px 0 0' : '8px',
                        '&:hover': { backgroundColor: colors.fondo }
                    }}
                >
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <TrendingUpIcon sx={{ color: colors.violeta }} />
                        <Typography variant="h6" sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>
                            Historial de Ganancias por Mes
                        </Typography>
                    </Box>
                </AccordionSummary>
                <AccordionDetails sx={{ p: 0 }}>
                    <TableContainer>
                        <Table size="small">
                            <TableHead>
                                <TableRow sx={{ backgroundColor: colors.fondo }}>
                                    <TableCell sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>Mes/Año</TableCell>
                                    <TableCell align="right" sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>Ventas</TableCell>
                                    <TableCell align="right" sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>Clases</TableCell>
                                    <TableCell align="right" sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>Total</TableCell>
                                    <TableCell sx={{ fontWeight: 'bold', color: colors.textoPrincipal }}>Detalles</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {historialGanancias.map((item, index) => (
                                    <TableRow key={index}>
                                        <TableCell sx={{ color: colors.textoPrincipal, fontWeight: 500 }}>
                                            {obtenerNombreMes(item.mes)} {item.anio}
                                        </TableCell>
                                        <TableCell align="right" sx={{ color: colors.azul }}>
                                            {formatearMoneda(item.totalVentas)}
                                        </TableCell>
                                        <TableCell align="right" sx={{ color: colors.naranja }}>
                                            {formatearMoneda(item.totalClases)}
                                        </TableCell>
                                        <TableCell align="right" sx={{ fontWeight: 'bold', color: colors.violeta }}>
                                            {formatearMoneda(item.totalVentas + item.totalClases)}
                                        </TableCell>
                                        <TableCell>
                                            <Accordion sx={{
                                                backgroundColor: 'transparent',
                                                boxShadow: 'none',
                                                '&:before': { display: 'none' }
                                            }}>
                                                <AccordionSummary
                                                    expandIcon={<ExpandMoreIcon sx={{ color: colors.violeta }} />}
                                                    sx={{ minHeight: 'auto', py: 0 }}
                                                >
                                                    <Typography variant="body2" sx={{ color: colors.azul }}>
                                                        Ver {item.detallesClases?.length || 0} detalles
                                                    </Typography>
                                                </AccordionSummary>
                                                <AccordionDetails>
                                                    {item.detallesClases && item.detallesClases.length > 0 ? (
                                                        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                                                            {item.detallesClases.map((clase, idx) => (
                                                                <Chip
                                                                    key={idx}
                                                                    label={`${clase.alumno}: ${formatearMoneda(clase.monto)}`}
                                                                    size="small"
                                                                    sx={{ backgroundColor: colors.fondo }}
                                                                />
                                                            ))}
                                                        </Box>
                                                    ) : (
                                                        <Typography variant="body2" sx={{ color: colors.textoSecundario }}>
                                                            No hay detalles disponibles
                                                        </Typography>
                                                    )}
                                                </AccordionDetails>
                                            </Accordion>
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                </AccordionDetails>
            </Accordion>

            {/* Botón Volver */}
            <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
                <Button
                    variant="contained"
                    sx={{
                        borderRadius: '40px',
                        backgroundColor: colors.textoSecundario,
                        color: colors.blanco,
                        textTransform: 'none',
                        fontWeight: 600,
                        '&:hover': {
                            backgroundColor: colors.textoSecundario,
                            opacity: 0.9
                        }
                    }}
                    onClick={() => navigate(-1)}
                >
                    Volver
                </Button>
            </Box>

            {/* Footer */}
            <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 3 }}>
                <Chip
                    label="Powered By PaBLo A."
                    size="small"
                    sx={{
                        backgroundColor: colors.error,
                        color: colors.blanco,
                        fontSize: '10px',
                        height: 24,
                        '&:hover': {
                            backgroundColor: colors.error,
                            opacity: 0.8,
                            transform: 'scale(1.05)',
                            transition: 'all 0.3s ease'
                        }
                    }}
                />
            </Box>
        </Box>
    );
};

export default VentaVarios;