import React, { useState, useEffect } from "react";
import {
    Box,
    Button,
    Card,
    CardContent,
    TextField,
    Typography,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    List,
    ListItem,
    ListItemText,
    IconButton,
    Paper,
    Chip,
    Grid,
    useMediaQuery,
    useTheme,
    MenuItem,
    Select,
    FormControl,
    InputLabel,
    Alert,
    Divider,
    Tabs,
    Tab,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Tooltip,
    Fab
} from "@mui/material";
import { ref, get, set, push, update, remove } from "firebase/database";
import { db } from "./firebaseConfig";
import { useNavigate } from "react-router-dom";
import ScienceIcon from '@mui/icons-material/Science';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';
import EditIcon from '@mui/icons-material/Edit';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import SaveIcon from '@mui/icons-material/Save';
import CancelIcon from '@mui/icons-material/Cancel';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import CalculateIcon from '@mui/icons-material/Calculate';
import ScaleIcon from '@mui/icons-material/Scale';
import PercentIcon from '@mui/icons-material/Percent';
import DownloadIcon from '@mui/icons-material/Download';
import ShareIcon from '@mui/icons-material/Share';
import PrintIcon from '@mui/icons-material/Print';
import PictureAsPdfIcon from '@mui/icons-material/PictureAsPdf';
import html2canvas from 'html2canvas';
import { styled } from '@mui/material/styles';

// Componente para el icono de química
const ChemistryIcon = styled(ScienceIcon)(({ theme }) => ({
    fontSize: 32,
    color: '#7c3aed',
    filter: 'drop-shadow(0 0 8px rgba(124, 58, 237, 0.3))',
}));

const FormulasCeramicas = () => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const isTablet = useMediaQuery(theme.breakpoints.between('sm', 'md'));
    const navigate = useNavigate();

    // Estados principales
    const [formulas, setFormulas] = useState([]);
    const [openDialog, setOpenDialog] = useState(false);
    const [openViewDialog, setOpenViewDialog] = useState(false);
    const [selectedFormula, setSelectedFormula] = useState(null);
    const [searchTerm, setSearchTerm] = useState("");
    const [filterType, setFilterType] = useState("todos");
    const [tabValue, setTabValue] = useState(0);

    // Estados para compartir
    const [openShareDialog, setOpenShareDialog] = useState(false);
    const [shareMethod, setShareMethod] = useState('whatsapp');

    // Estado para nueva fórmula
    const [newFormula, setNewFormula] = useState({
        nombre: "",
        tipo: "esmalte",
        descripcion: "",
        materiales: [],
        rendimiento: "",
        temperatura: "",
        observaciones: ""
    });

    // Estado para material en edición
    const [materialEdit, setMaterialEdit] = useState({
        nombre: "",
        cantidad: "",
        unidad: "gramos",
        tipo: "peso"
    });

    // Estados para el diálogo de materiales
    const [openMaterialDialog, setOpenMaterialDialog] = useState(false);
    const [editingMaterialIndex, setEditingMaterialIndex] = useState(null);

    // Tipos de fórmulas
    const tiposFormula = [
        { value: "esmalte", label: "Esmalte" },
        { value: "pasta", label: "Pasta Cerámica" },
        { value: "engobe", label: "Engobe" },
        { value: "vidriado", label: "Vidriado" },
        { value: "otro", label: "Otro" }
    ];

    // Unidades de medida
    const unidades = [
        { value: "gramos", label: "Gramos (g)" },
        { value: "kilogramos", label: "Kilogramos (kg)" },
        { value: "partes", label: "Partes" },
        { value: "porcentaje", label: "%" }
    ];

    // Tipos de medición
    const tiposMedicion = [
        { value: "peso", label: "Peso", icon: <ScaleIcon /> },
        { value: "partes", label: "Partes", icon: <CalculateIcon /> },
        { value: "porcentaje", label: "Porcentaje", icon: <PercentIcon /> }
    ];

    // Cargar fórmulas de Firebase
    useEffect(() => {
        cargarFormulas();
    }, []);

    const cargarFormulas = async () => {
        try {
            const formulasRef = ref(db, "formulas");
            const snapshot = await get(formulasRef);
            if (snapshot.exists()) {
                const data = snapshot.val();
                const formulasList = Object.entries(data).map(([key, value]) => ({
                    ...value,
                    id: key,
                    materiales: value.materiales || []
                }));
                setFormulas(formulasList);
            } else {
                setFormulas([]);
            }
        } catch (error) {
            console.error("Error al cargar fórmulas:", error);
            alert("Error al cargar las fórmulas");
        }
    };

    // Guardar nueva fórmula
    const guardarFormula = async () => {
        if (!newFormula.nombre.trim()) {
            alert("Por favor, ingrese un nombre para la fórmula");
            return;
        }

        if (newFormula.materiales.length === 0) {
            alert("Por favor, agregue al menos un material");
            return;
        }

        try {
            const formulasRef = ref(db, "formulas");
            const nuevaFormulaRef = push(formulasRef);

            const formulaData = {
                ...newFormula,
                fechaCreacion: new Date().toISOString(),
                materiales: newFormula.materiales.map(m => ({
                    ...m,
                    cantidad: parseFloat(m.cantidad) || 0
                }))
            };

            await set(nuevaFormulaRef, formulaData);

            setOpenDialog(false);
            resetNewFormula();
            cargarFormulas();

            alert("¡Fórmula guardada exitosamente!");
        } catch (error) {
            console.error("Error al guardar fórmula:", error);
            alert("Error al guardar la fórmula");
        }
    };

    // Editar fórmula
    const editarFormula = async () => {
        if (!selectedFormula) return;

        try {
            await update(ref(db, `formulas/${selectedFormula.id}`), {
                nombre: selectedFormula.nombre,
                tipo: selectedFormula.tipo,
                descripcion: selectedFormula.descripcion,
                materiales: selectedFormula.materiales,
                rendimiento: selectedFormula.rendimiento,
                temperatura: selectedFormula.temperatura,
                observaciones: selectedFormula.observaciones
            });

            setOpenViewDialog(false);
            cargarFormulas();
            alert("¡Fórmula actualizada exitosamente!");
        } catch (error) {
            console.error("Error al editar fórmula:", error);
            alert("Error al editar la fórmula");
        }
    };

    // Eliminar fórmula
    const eliminarFormula = async (id) => {
        if (!window.confirm("¿Estás seguro de eliminar esta fórmula?")) return;

        try {
            await remove(ref(db, `formulas/${id}`));
            cargarFormulas();
            setOpenViewDialog(false);
            alert("Fórmula eliminada exitosamente");
        } catch (error) {
            console.error("Error al eliminar fórmula:", error);
            alert("Error al eliminar la fórmula");
        }
    };

    // Copiar fórmula
    const copiarFormula = (formula) => {
        setNewFormula({
            nombre: `${formula.nombre} (Copia)`,
            tipo: formula.tipo,
            descripcion: formula.descripcion || "",
            materiales: formula.materiales.map(m => ({ ...m })),
            rendimiento: formula.rendimiento || "",
            temperatura: formula.temperatura || "",
            observaciones: formula.observaciones || ""
        });
        setOpenDialog(true);
    };

    // Resetear nueva fórmula
    const resetNewFormula = () => {
        setNewFormula({
            nombre: "",
            tipo: "esmalte",
            descripcion: "",
            materiales: [],
            rendimiento: "",
            temperatura: "",
            observaciones: ""
        });
        setMaterialEdit({
            nombre: "",
            cantidad: "",
            unidad: "gramos",
            tipo: "peso"
        });
        setEditingMaterialIndex(null);
    };

    // Agregar material
    const agregarMaterial = () => {
        if (!materialEdit.nombre.trim()) {
            alert("Por favor, ingrese el nombre del material");
            return;
        }

        if (!materialEdit.cantidad || parseFloat(materialEdit.cantidad) <= 0) {
            alert("Por favor, ingrese una cantidad válida");
            return;
        }

        const material = {
            ...materialEdit,
            cantidad: parseFloat(materialEdit.cantidad)
        };

        if (editingMaterialIndex !== null) {
            // Editar material existente
            const nuevosMateriales = [...newFormula.materiales];
            nuevosMateriales[editingMaterialIndex] = material;
            setNewFormula({ ...newFormula, materiales: nuevosMateriales });
            setEditingMaterialIndex(null);
        } else {
            // Agregar nuevo material
            setNewFormula({
                ...newFormula,
                materiales: [...newFormula.materiales, material]
            });
        }

        setMaterialEdit({
            nombre: "",
            cantidad: "",
            unidad: "gramos",
            tipo: "peso"
        });
        setOpenMaterialDialog(false);
    };

    // Editar material
    const editarMaterial = (index) => {
        const material = newFormula.materiales[index];
        setMaterialEdit({ ...material });
        setEditingMaterialIndex(index);
        setOpenMaterialDialog(true);
    };

    // Eliminar material
    const eliminarMaterial = (index) => {
        const nuevosMateriales = newFormula.materiales.filter((_, i) => i !== index);
        setNewFormula({ ...newFormula, materiales: nuevosMateriales });
    };

    // Calcular totales
    const calcularTotales = (materiales) => {
        const totalPeso = materiales.reduce((sum, m) => {
            if (m.tipo === "peso") return sum + (m.cantidad || 0);
            return sum;
        }, 0);

        const totalPartes = materiales.reduce((sum, m) => {
            if (m.tipo === "partes") return sum + (m.cantidad || 0);
            return sum;
        }, 0);

        const totalPorcentaje = materiales.reduce((sum, m) => {
            if (m.tipo === "porcentaje") return sum + (m.cantidad || 0);
            return sum;
        }, 0);

        return { totalPeso, totalPartes, totalPorcentaje };
    };

    // Filtrar fórmulas
    const formulasFiltradas = formulas.filter(formula => {
        const matchSearch = formula.nombre.toLowerCase().includes(searchTerm.toLowerCase()) ||
            formula.descripcion?.toLowerCase().includes(searchTerm.toLowerCase());
        const matchType = filterType === "todos" || formula.tipo === filterType;
        return matchSearch && matchType;
    });

    // ========== FUNCIÓN PARA COMPARTIR ==========
    const compartirFormula = () => {
        setOpenShareDialog(true);
    };

    // ========== EJECUTAR COMPARTIR ==========
    const ejecutarCompartir = async () => {
        const mensaje = `🧪 *Fórmula: ${selectedFormula.nombre}*%0A%0A` +
            `📋 *Tipo:* ${tiposFormula.find(t => t.value === selectedFormula.tipo)?.label || selectedFormula.tipo}%0A` +
            `📝 *Descripción:* ${selectedFormula.descripcion || 'Sin descripción'}%0A` +
            `🌡️ *Temperatura:* ${selectedFormula.temperatura || 'No especificada'}°C%0A%0A` +
            `🔬 *Materiales:*%0A` +
            selectedFormula.materiales.map((m, i) =>
                `${i + 1}. ${m.nombre}: ${m.cantidad} ${unidades.find(u => u.value === m.unidad)?.label || m.unidad}`
            ).join('%0A');

        let url = '';

        switch (shareMethod) {
            case 'whatsapp':
                url = `https://wa.me/?text=${mensaje}`;
                break;
            case 'whatsapp_number':
                const phone = prompt('Ingresa el número de teléfono (con código de país, ej: 549XXXXXXXXX):');
                if (phone) {
                    url = `https://wa.me/${phone}?text=${mensaje}`;
                } else {
                    setOpenShareDialog(false);
                    return;
                }
                break;
            case 'instagram':
                // Copiar al portapapeles y abrir Instagram
                try {
                    await navigator.clipboard.writeText(
                        `🧪 Fórmula: ${selectedFormula.nombre}\n` +
                        `Tipo: ${tiposFormula.find(t => t.value === selectedFormula.tipo)?.label || selectedFormula.tipo}\n\n` +
                        `Materiales:\n` +
                        selectedFormula.materiales.map(m =>
                            `  - ${m.nombre}: ${m.cantidad} ${unidades.find(u => u.value === m.unidad)?.label || m.unidad}`
                        ).join('\n')
                    );
                    alert('✅ Texto copiado al portapapeles. Abriendo Instagram...');
                    window.open('https://www.instagram.com/', '_blank');
                } catch (error) {
                    console.error('Error:', error);
                }
                setOpenShareDialog(false);
                return;
            case 'image':
                await descargarComoImagen();
                setOpenShareDialog(false);
                return;
            default:
                setOpenShareDialog(false);
                return;
        }

        if (url) {
            window.open(url, '_blank');
        }
        setOpenShareDialog(false);
    };

    // ========== COMPONENTE NOTA IMPRIMIBLE ==========
    const NotaImprimible = ({ formula, totales }) => {
        return (
            <Box
                id="nota-imprimible"
                sx={{
                    padding: 3,
                    backgroundColor: 'white',
                    borderRadius: 2,
                    boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
                    maxWidth: 800,
                    margin: '0 auto',
                    fontFamily: 'Arial, sans-serif',
                }}
            >
                {/* Encabezado */}
                <Box sx={{
                    borderBottom: '3px solid #7c3aed',
                    pb: 2,
                    mb: 3,
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    flexWrap: 'wrap'
                }}>
                    <Box>
                        <Typography variant="h5" sx={{ fontWeight: 'bold', color: '#1e293b' }}>
                            🧪 {formula.nombre}
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                            {new Date().toLocaleDateString('es-ES', {
                                year: 'numeric',
                                month: 'long',
                                day: 'numeric'
                            })}
                        </Typography>
                    </Box>
                    <Chip
                        label={tiposFormula.find(t => t.value === formula.tipo)?.label || formula.tipo}
                        sx={{
                            backgroundColor: '#7c3aed',
                            color: 'white',
                            fontWeight: 'bold'
                        }}
                    />
                </Box>

                {/* Información general */}
                <Grid container spacing={2} sx={{ mb: 3 }}>
                    {formula.descripcion && (
                        <Grid item xs={12}>
                            <Typography variant="subtitle2" color="text.secondary">Descripción</Typography>
                            <Typography variant="body1">{formula.descripcion}</Typography>
                        </Grid>
                    )}
                    {formula.temperatura && (
                        <Grid item xs={12} sm={6}>
                            <Typography variant="subtitle2" color="text.secondary">Temperatura</Typography>
                            <Typography variant="body1">{formula.temperatura}°C</Typography>
                        </Grid>
                    )}
                    {formula.rendimiento && (
                        <Grid item xs={12} sm={6}>
                            <Typography variant="subtitle2" color="text.secondary">Rendimiento</Typography>
                            <Typography variant="body1">{formula.rendimiento}</Typography>
                        </Grid>
                    )}
                </Grid>

                {/* Materiales */}
                <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#1e293b', mb: 2 }}>
                    📋 Materiales
                </Typography>

                <TableContainer component={Paper} elevation={0} sx={{
                    border: '2px solid #e2e8f0',
                    borderRadius: 2,
                    mb: 3,
                    overflow: 'hidden'
                }}>
                    <Table>
                        <TableHead>
                            <TableRow sx={{ backgroundColor: '#f8fafc' }}>
                                <TableCell sx={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Material</TableCell>
                                <TableCell align="right" sx={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Cantidad</TableCell>
                                <TableCell align="center" sx={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Unidad</TableCell>
                                <TableCell align="center" sx={{ fontWeight: 'bold', fontSize: '0.9rem' }}>Tipo</TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {formula.materiales.map((material, index) => (
                                <TableRow key={index} sx={{
                                    '&:nth-of-type(odd)': { backgroundColor: '#fafafa' }
                                }}>
                                    <TableCell sx={{ fontWeight: '500' }}>{material.nombre}</TableCell>
                                    <TableCell align="right" sx={{ fontWeight: 'bold' }}>
                                        {material.cantidad}
                                    </TableCell>
                                    <TableCell align="center">
                                        <Chip
                                            label={unidades.find(u => u.value === material.unidad)?.label || material.unidad}
                                            size="small"
                                            variant="outlined"
                                            sx={{ fontSize: '0.7rem' }}
                                        />
                                    </TableCell>
                                    <TableCell align="center">
                                        <Chip
                                            label={tiposMedicion.find(t => t.value === material.tipo)?.label || material.tipo}
                                            size="small"
                                            variant="outlined"
                                            color="primary"
                                            sx={{ fontSize: '0.7rem' }}
                                        />
                                    </TableCell>
                                </TableRow>
                            ))}
                        </TableBody>
                    </Table>
                </TableContainer>

                {/* Totales */}
                <Box sx={{
                    display: 'flex',
                    gap: 2,
                    flexWrap: 'wrap',
                    mb: 3,
                    p: 2,
                    backgroundColor: '#f8fafc',
                    borderRadius: 2
                }}>
                    {totales.totalPeso > 0 && (
                        <Chip
                            icon={<ScaleIcon />}
                            label={`Peso total: ${totales.totalPeso}g`}
                            color="primary"
                            variant="outlined"
                            sx={{ fontWeight: 'bold' }}
                        />
                    )}
                    {totales.totalPartes > 0 && (
                        <Chip
                            icon={<CalculateIcon />}
                            label={`Total partes: ${totales.totalPartes}`}
                            color="secondary"
                            variant="outlined"
                            sx={{ fontWeight: 'bold' }}
                        />
                    )}
                    {totales.totalPorcentaje > 0 && (
                        <Chip
                            icon={<PercentIcon />}
                            label={`Total: ${totales.totalPorcentaje}%`}
                            color="info"
                            variant="outlined"
                            sx={{ fontWeight: 'bold' }}
                        />
                    )}
                </Box>

                {/* Observaciones */}
                {formula.observaciones && (
                    <Box sx={{
                        mt: 2,
                        p: 2,
                        backgroundColor: '#fef3c7',
                        borderRadius: 2,
                        border: '1px solid #f59e0b'
                    }}>
                        <Typography variant="subtitle2" color="text.secondary">📝 Observaciones</Typography>
                        <Typography variant="body1">{formula.observaciones}</Typography>
                    </Box>
                )}

                {/* Footer */}
                <Box sx={{
                    mt: 3,
                    pt: 2,
                    borderTop: '1px solid #e2e8f0',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    flexWrap: 'wrap',
                    gap: 1
                }}>
                    <Typography variant="caption" color="text.secondary">
                        📅 Creada: {new Date(formula.fechaCreacion).toLocaleDateString()}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                        🏷️ {formula.tipo}
                    </Typography>
                </Box>
            </Box>
        );
    };

    // ========== FUNCIONES DE DESCARGAR/IMPRIMIR ==========
    const descargarComoImagen = async () => {
        try {
            const element = document.getElementById('nota-imprimible');
            if (!element) {
                alert('No se encontró la nota para descargar');
                return;
            }

            const canvas = await html2canvas(element, {
                scale: 2,
                backgroundColor: '#ffffff',
                allowTaint: true,
                useCORS: true,
                logging: false,
            });

            const link = document.createElement('a');
            link.download = `formula-${selectedFormula.nombre.replace(/\s+/g, '-').toLowerCase()}.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
        } catch (error) {
            console.error('Error al descargar:', error);
            alert('Error al descargar la imagen. Por favor, intenta de nuevo.');
        }
    };

    const imprimirNota = () => {
        const printContent = document.getElementById('nota-imprimible');
        if (!printContent) {
            alert('No se encontró la nota para imprimir');
            return;
        }

        const printWindow = window.open('', '_blank');
        if (!printWindow) {
            alert('Por favor, permite las ventanas emergentes para imprimir');
            return;
        }

        printWindow.document.write(`
            <html>
                <head>
                    <title>Fórmula: ${selectedFormula.nombre}</title>
                    <style>
                        body { 
                            margin: 0; 
                            padding: 20px; 
                            font-family: Arial, sans-serif;
                            background: white;
                        }
                        * {
                            -webkit-print-color-adjust: exact !important;
                            print-color-adjust: exact !important;
                        }
                        @media print {
                            body { padding: 0; }
                            #print-content { margin: 0 auto; }
                        }
                    </style>
                </head>
                <body>
                    <div id="print-content">
                        ${printContent.outerHTML}
                    </div>
                    <script>
                        window.onload = function() {
                            window.print();
                            setTimeout(function() {
                                window.close();
                            }, 1000);
                        };
                    <\/script>
                </body>
            </html>
        `);
        printWindow.document.close();
    };

    // ========== DIÁLOGO PARA VER FÓRMULA ==========
    const VerFormulaDialog = () => {
        if (!selectedFormula) return null;

        const totales = calcularTotales(selectedFormula.materiales || []);

        return (
            <Dialog
                open={openViewDialog}
                onClose={() => setOpenViewDialog(false)}
                fullScreen={isMobile}
                fullWidth
                maxWidth="md"
            >
                <DialogTitle sx={{
                    backgroundColor: '#7c3aed',
                    color: 'white',
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    flexWrap: 'wrap',
                    gap: 1
                }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <ChemistryIcon sx={{ color: 'white' }} />
                        <Typography variant="h6">{selectedFormula.nombre}</Typography>
                    </Box>
                    <Box>
                        <Chip
                            label={tiposFormula.find(t => t.value === selectedFormula.tipo)?.label || selectedFormula.tipo}
                            size="small"
                            sx={{ backgroundColor: 'rgba(255,255,255,0.2)', color: 'white' }}
                        />
                    </Box>
                </DialogTitle>

                <DialogContent sx={{ mt: 2, maxHeight: '70vh', overflow: 'auto' }}>
                    {/* Tabs para alternar entre vistas */}
                    <Tabs value={tabValue} onChange={(e, v) => setTabValue(v)} sx={{ mb: 2 }}>
                        <Tab label="Vista Detallada" />
                        <Tab label="Nota Imprimible" />
                    </Tabs>

                    {tabValue === 0 ? (
                        // Vista detallada
                        <Grid container spacing={2}>
                            <Grid item xs={12} md={6}>
                                <Typography variant="subtitle2" color="text.secondary">Descripción</Typography>
                                <Typography variant="body1">{selectedFormula.descripcion || "Sin descripción"}</Typography>
                            </Grid>
                            <Grid item xs={12} md={6}>
                                <Typography variant="subtitle2" color="text.secondary">Temperatura</Typography>
                                <Typography variant="body1">{selectedFormula.temperatura || "No especificada"} °C</Typography>
                            </Grid>
                            <Grid item xs={12} md={6}>
                                <Typography variant="subtitle2" color="text.secondary">Rendimiento</Typography>
                                <Typography variant="body1">{selectedFormula.rendimiento || "No especificado"}</Typography>
                            </Grid>
                            <Grid item xs={12}>
                                <Divider sx={{ my: 2 }} />
                                <Typography variant="h6" sx={{ mb: 2 }}>Materiales</Typography>
                                <TableContainer component={Paper} elevation={0} sx={{ border: '1px solid #e2e8f0' }}>
                                    <Table>
                                        <TableHead>
                                            <TableRow sx={{ backgroundColor: '#f8fafc' }}>
                                                <TableCell>Material</TableCell>
                                                <TableCell align="right">Cantidad</TableCell>
                                                <TableCell align="center">Unidad</TableCell>
                                                <TableCell align="center">Tipo</TableCell>
                                            </TableRow>
                                        </TableHead>
                                        <TableBody>
                                            {selectedFormula.materiales.map((material, index) => (
                                                <TableRow key={index}>
                                                    <TableCell>{material.nombre}</TableCell>
                                                    <TableCell align="right">{material.cantidad}</TableCell>
                                                    <TableCell align="center">
                                                        <Chip
                                                            label={unidades.find(u => u.value === material.unidad)?.label || material.unidad}
                                                            size="small"
                                                            variant="outlined"
                                                        />
                                                    </TableCell>
                                                    <TableCell align="center">
                                                        <Chip
                                                            label={tiposMedicion.find(t => t.value === material.tipo)?.label || material.tipo}
                                                            size="small"
                                                            icon={tiposMedicion.find(t => t.value === material.tipo)?.icon}
                                                            variant="outlined"
                                                            color="primary"
                                                        />
                                                    </TableCell>
                                                </TableRow>
                                            ))}
                                        </TableBody>
                                    </Table>
                                </TableContainer>
                                <Box sx={{ mt: 2, display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                                    {totales.totalPeso > 0 && (
                                        <Chip
                                            icon={<ScaleIcon />}
                                            label={`Peso total: ${totales.totalPeso}g`}
                                            color="primary"
                                            variant="outlined"
                                        />
                                    )}
                                    {totales.totalPartes > 0 && (
                                        <Chip
                                            icon={<CalculateIcon />}
                                            label={`Total partes: ${totales.totalPartes}`}
                                            color="secondary"
                                            variant="outlined"
                                        />
                                    )}
                                    {totales.totalPorcentaje > 0 && (
                                        <Chip
                                            icon={<PercentIcon />}
                                            label={`Total: ${totales.totalPorcentaje}%`}
                                            color="info"
                                            variant="outlined"
                                        />
                                    )}
                                </Box>
                            </Grid>
                            {selectedFormula.observaciones && (
                                <Grid item xs={12}>
                                    <Divider sx={{ my: 2 }} />
                                    <Typography variant="subtitle2" color="text.secondary">Observaciones</Typography>
                                    <Typography variant="body1">{selectedFormula.observaciones}</Typography>
                                </Grid>
                            )}
                            <Grid item xs={12}>
                                <Typography variant="caption" color="text.secondary">
                                    Creada: {new Date(selectedFormula.fechaCreacion).toLocaleDateString()}
                                </Typography>
                            </Grid>
                        </Grid>
                    ) : (
                        // Nota imprimible
                        <NotaImprimible
                            formula={selectedFormula}
                            totales={totales}
                        />
                    )}
                </DialogContent>

                <DialogActions sx={{
                    p: 2,
                    flexWrap: 'wrap',
                    gap: 1,
                    flexDirection: isMobile ? 'column' : 'row',
                    alignItems: 'stretch'
                }}>
                    <Box sx={{
                        display: 'flex',
                        gap: 1,
                        flexWrap: 'wrap',
                        width: isMobile ? '100%' : 'auto',
                        justifyContent: isMobile ? 'center' : 'flex-start'
                    }}>
                        <Button
                            startIcon={<ShareIcon />}
                            onClick={compartirFormula}
                            variant="contained"
                            sx={{
                                backgroundColor: '#7c3aed',
                                '&:hover': { backgroundColor: '#6d28d9' },
                                flex: isMobile ? 1 : 'auto'
                            }}
                        >
                            Compartir
                        </Button>

                        <Button
                            startIcon={<DownloadIcon />}
                            onClick={descargarComoImagen}
                            variant="outlined"
                            sx={{
                                borderColor: '#7c3aed',
                                color: '#7c3aed',
                                '&:hover': {
                                    borderColor: '#6d28d9',
                                    backgroundColor: 'rgba(124, 58, 237, 0.05)'
                                },
                                flex: isMobile ? 1 : 'auto'
                            }}
                        >
                            Descargar
                        </Button>

                        <Button
                            startIcon={<PrintIcon />}
                            onClick={imprimirNota}
                            variant="outlined"
                            sx={{
                                borderColor: '#10b981',
                                color: '#10b981',
                                '&:hover': {
                                    borderColor: '#059669',
                                    backgroundColor: 'rgba(16, 185, 129, 0.05)'
                                },
                                flex: isMobile ? 1 : 'auto'
                            }}
                        >
                            Imprimir
                        </Button>
                    </Box>

                    <Box sx={{
                        display: 'flex',
                        gap: 1,
                        flexWrap: 'wrap',
                        width: isMobile ? '100%' : 'auto',
                        justifyContent: isMobile ? 'center' : 'flex-end'
                    }}>
                        <Button
                            startIcon={<ContentCopyIcon />}
                            onClick={() => {
                                copiarFormula(selectedFormula);
                                setOpenViewDialog(false);
                            }}
                            color="secondary"
                            sx={{ flex: isMobile ? 1 : 'auto' }}
                        >
                            Copiar
                        </Button>
                        <Button
                            startIcon={<EditIcon />}
                            onClick={() => {
                                setOpenViewDialog(false);
                                setNewFormula({ ...selectedFormula });
                                setOpenDialog(true);
                            }}
                            color="primary"
                            sx={{ flex: isMobile ? 1 : 'auto' }}
                        >
                            Editar
                        </Button>
                        <Button
                            startIcon={<DeleteIcon />}
                            onClick={() => eliminarFormula(selectedFormula.id)}
                            color="error"
                            sx={{ flex: isMobile ? 1 : 'auto' }}
                        >
                            Eliminar
                        </Button>
                        <Button
                            onClick={() => setOpenViewDialog(false)}
                            sx={{ flex: isMobile ? 1 : 'auto' }}
                        >
                            Cerrar
                        </Button>
                    </Box>
                </DialogActions>
            </Dialog>
        );
    };

    // ========== RENDER PRINCIPAL ==========
    return (
        <Box sx={{ p: isMobile ? 1 : 3 }}>
            {/* Header con título y botón */}
            <Box sx={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                mb: 3,
                gap: 2
            }}>
                <Box sx={{ width: '100%' }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                        <ChemistryIcon />
                        <Typography variant={isMobile ? "h5" : "h4"} sx={{ fontWeight: 'bold', color: '#1e293b' }}>
                            Fórmulas Varias
                        </Typography>
                    </Box>
                    <Typography variant="subtitle1" sx={{ color: '#64748b', ml: 6 }}>
                        Creá y guardá lo que quieras
                    </Typography>
                </Box>
                <Button
                    variant="contained"
                    startIcon={<AddIcon />}
                    onClick={() => {
                        resetNewFormula();
                        setOpenDialog(true);
                    }}
                    sx={{
                        backgroundColor: '#7c3aed',
                        '&:hover': { backgroundColor: '#6d28d9' },
                        minWidth: 200,
                        width: isMobile ? '100%' : 'auto',
                    }}
                >
                    Nueva Fórmula
                </Button>
            </Box>

            {/* Filtros */}
            <Paper sx={{ p: 2, mb: 3 }}>
                <Grid container spacing={2} alignItems="center">
                    <Grid item xs={12} md={6}>
                        <TextField
                            fullWidth
                            placeholder="Buscar fórmulas..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            size={isMobile ? "small" : "medium"}
                        />
                    </Grid>
                    <Grid item xs={12} md={6}>
                        <FormControl fullWidth size={isMobile ? "small" : "medium"}>
                            <InputLabel>Filtrar por tipo</InputLabel>
                            <Select
                                value={filterType}
                                onChange={(e) => setFilterType(e.target.value)}
                                label="Filtrar por tipo"
                            >
                                <MenuItem value="todos">Todos</MenuItem>
                                {tiposFormula.map(tipo => (
                                    <MenuItem key={tipo.value} value={tipo.value}>
                                        {tipo.label}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Grid>
                </Grid>
            </Paper>

            {/* Lista de fórmulas */}
            {formulasFiltradas.length === 0 ? (
                <Paper sx={{ p: 4, textAlign: 'center' }}>
                    <Typography variant="body1" color="text.secondary">
                        {searchTerm ? "No se encontraron fórmulas" : "No hay fórmulas aún. ¡Crea tu primera fórmula!"}
                    </Typography>
                </Paper>
            ) : (
                <Grid container spacing={2}>
                    {formulasFiltradas.map((formula) => (
                        <Grid item xs={12} md={6} lg={4} key={formula.id}>
                            <Card
                                sx={{
                                    height: '100%',
                                    cursor: 'pointer',
                                    transition: 'all 0.3s ease',
                                    '&:hover': {
                                        transform: 'translateY(-4px)',
                                        boxShadow: 4
                                    }
                                }}
                                onClick={() => {
                                    setSelectedFormula(formula);
                                    setOpenViewDialog(true);
                                    setTabValue(0);
                                }}
                            >
                                <CardContent>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', mb: 1 }}>
                                        <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                                            {formula.nombre}
                                        </Typography>
                                        <Chip
                                            label={tiposFormula.find(t => t.value === formula.tipo)?.label || formula.tipo}
                                            size="small"
                                            color="primary"
                                            variant="outlined"
                                        />
                                    </Box>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                        {formula.descripcion || "Sin descripción"}
                                    </Typography>
                                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                                        <Chip
                                            label={`${formula.materiales?.length || 0} materiales`}
                                            size="small"
                                            variant="outlined"
                                        />
                                        {formula.temperatura && (
                                            <Chip
                                                label={`${formula.temperatura}°C`}
                                                size="small"
                                                variant="outlined"
                                                color="warning"
                                            />
                                        )}
                                    </Box>
                                    <Box sx={{ mt: 2, display: 'flex', gap: 1 }}>
                                        <Button
                                            size="small"
                                            startIcon={<ContentCopyIcon />}
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                copiarFormula(formula);
                                            }}
                                        >
                                            Copiar
                                        </Button>
                                    </Box>
                                </CardContent>
                            </Card>
                        </Grid>
                    ))}
                </Grid>
            )}

            {/* Diálogo para crear/editar fórmula */}
            <Dialog
                open={openDialog}
                onClose={() => setOpenDialog(false)}
                fullScreen={isMobile}
                fullWidth
                maxWidth="md"
            >
                <DialogTitle sx={{ backgroundColor: '#7c3aed', color: 'white' }}>
                    {newFormula.id ? "Editar Fórmula" : "Nueva Fórmula"}
                </DialogTitle>
                <DialogContent sx={{ mt: 2 }}>
                    <Grid container spacing={2}>
                        <Grid item xs={12} md={6}>
                            <TextField
                                fullWidth
                                label="Nombre de la fórmula"
                                value={newFormula.nombre}
                                onChange={(e) => setNewFormula({ ...newFormula, nombre: e.target.value })}
                                required
                            />
                        </Grid>
                        <Grid item xs={12} md={6}>
                            <FormControl fullWidth>
                                <InputLabel>Tipo</InputLabel>
                                <Select
                                    value={newFormula.tipo}
                                    onChange={(e) => setNewFormula({ ...newFormula, tipo: e.target.value })}
                                    label="Tipo"
                                >
                                    {tiposFormula.map(tipo => (
                                        <MenuItem key={tipo.value} value={tipo.value}>
                                            {tipo.label}
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={12}>
                            <TextField
                                fullWidth
                                label="Descripción"
                                multiline
                                rows={2}
                                value={newFormula.descripcion}
                                onChange={(e) => setNewFormula({ ...newFormula, descripcion: e.target.value })}
                            />
                        </Grid>
                        <Grid item xs={12} md={6}>
                            <TextField
                                fullWidth
                                label="Temperatura (°C)"
                                type="number"
                                value={newFormula.temperatura}
                                onChange={(e) => setNewFormula({ ...newFormula, temperatura: e.target.value })}
                            />
                        </Grid>
                        <Grid item xs={12} md={6}>
                            <TextField
                                fullWidth
                                label="Rendimiento (ej: 1kg)"
                                value={newFormula.rendimiento}
                                onChange={(e) => setNewFormula({ ...newFormula, rendimiento: e.target.value })}
                            />
                        </Grid>
                        <Grid item xs={12}>
                            <Divider sx={{ my: 2 }}>
                                <Chip label="Materiales" />
                            </Divider>

                            {/* Lista de materiales */}
                            {newFormula.materiales.map((material, index) => (
                                <Paper key={index} sx={{ p: 1, mb: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <Box>
                                        <Typography variant="body1">{material.nombre}</Typography>
                                        <Typography variant="caption" color="text.secondary">
                                            {material.cantidad} {unidades.find(u => u.value === material.unidad)?.label || material.unidad} -
                                            {tiposMedicion.find(t => t.value === material.tipo)?.label || material.tipo}
                                        </Typography>
                                    </Box>
                                    <Box>
                                        <IconButton size="small" onClick={() => editarMaterial(index)}>
                                            <EditIcon fontSize="small" />
                                        </IconButton>
                                        <IconButton size="small" onClick={() => eliminarMaterial(index)}>
                                            <DeleteIcon fontSize="small" color="error" />
                                        </IconButton>
                                    </Box>
                                </Paper>
                            ))}

                            <Button
                                variant="outlined"
                                startIcon={<AddIcon />}
                                onClick={() => {
                                    setEditingMaterialIndex(null);
                                    setMaterialEdit({
                                        nombre: "",
                                        cantidad: "",
                                        unidad: "gramos",
                                        tipo: "peso"
                                    });
                                    setOpenMaterialDialog(true);
                                }}
                                fullWidth
                                sx={{ mt: 1 }}
                            >
                                Agregar Material
                            </Button>
                        </Grid>
                        <Grid item xs={12}>
                            <TextField
                                fullWidth
                                label="Observaciones"
                                multiline
                                rows={2}
                                value={newFormula.observaciones}
                                onChange={(e) => setNewFormula({ ...newFormula, observaciones: e.target.value })}
                            />
                        </Grid>
                    </Grid>
                </DialogContent>
                <DialogActions sx={{ p: 2 }}>
                    <Button onClick={() => setOpenDialog(false)}>Cancelar</Button>
                    <Button
                        variant="contained"
                        onClick={guardarFormula}
                        sx={{ backgroundColor: '#7c3aed', '&:hover': { backgroundColor: '#6d28d9' } }}
                    >
                        Guardar
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Diálogo para agregar/editar material */}
            <Dialog
                open={openMaterialDialog}
                onClose={() => setOpenMaterialDialog(false)}
                fullScreen={isMobile}
                fullWidth
                maxWidth="sm"
            >
                <DialogTitle>
                    {editingMaterialIndex !== null ? "Editar Material" : "Agregar Material"}
                </DialogTitle>
                <DialogContent>
                    <Grid container spacing={2} sx={{ mt: 1 }}>
                        <Grid item xs={12}>
                            <TextField
                                fullWidth
                                label="Nombre del material"
                                value={materialEdit.nombre}
                                onChange={(e) => setMaterialEdit({ ...materialEdit, nombre: e.target.value })}
                                required
                            />
                        </Grid>
                        <Grid item xs={12} md={6}>
                            <TextField
                                fullWidth
                                label="Cantidad"
                                type="number"
                                value={materialEdit.cantidad}
                                onChange={(e) => setMaterialEdit({ ...materialEdit, cantidad: e.target.value })}
                                required
                            />
                        </Grid>
                        <Grid item xs={12} md={6}>
                            <FormControl fullWidth>
                                <InputLabel>Unidad</InputLabel>
                                <Select
                                    value={materialEdit.unidad}
                                    onChange={(e) => setMaterialEdit({ ...materialEdit, unidad: e.target.value })}
                                    label="Unidad"
                                >
                                    {unidades.map(unidad => (
                                        <MenuItem key={unidad.value} value={unidad.value}>
                                            {unidad.label}
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={12}>
                            <FormControl fullWidth>
                                <InputLabel>Tipo de medición</InputLabel>
                                <Select
                                    value={materialEdit.tipo}
                                    onChange={(e) => setMaterialEdit({ ...materialEdit, tipo: e.target.value })}
                                    label="Tipo de medición"
                                >
                                    {tiposMedicion.map(tipo => (
                                        <MenuItem key={tipo.value} value={tipo.value}>
                                            {tipo.icon} {tipo.label}
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                        </Grid>
                    </Grid>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setOpenMaterialDialog(false)}>Cancelar</Button>
                    <Button
                        variant="contained"
                        onClick={agregarMaterial}
                        sx={{ backgroundColor: '#7c3aed', '&:hover': { backgroundColor: '#6d28d9' } }}
                    >
                        {editingMaterialIndex !== null ? "Actualizar" : "Agregar"}
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Diálogo para ver fórmula */}
            <VerFormulaDialog />

            {/* Diálogo para compartir */}
            <Dialog
                open={openShareDialog}
                onClose={() => setOpenShareDialog(false)}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle sx={{ backgroundColor: '#7c3aed', color: 'white' }}>
                    <Box display="flex" alignItems="center" gap={1}>
                        <ShareIcon /> Compartir Fórmula
                    </Box>
                </DialogTitle>
                <DialogContent sx={{ mt: 2 }}>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Selecciona cómo quieres compartir la fórmula:
                    </Typography>

                    <Grid container spacing={2}>
                        <Grid item xs={12}>
                            <Button
                                fullWidth
                                variant={shareMethod === 'whatsapp' ? 'contained' : 'outlined'}
                                startIcon={<img src="https://cdn.jsdelivr.net/npm/simple-icons@v8/icons/whatsapp.svg" width="24" height="24" alt="WhatsApp" />}
                                onClick={() => setShareMethod('whatsapp')}
                                sx={{
                                    justifyContent: 'flex-start',
                                    backgroundColor: shareMethod === 'whatsapp' ? '#25D366' : 'transparent',
                                    borderColor: '#25D366',
                                    color: shareMethod === 'whatsapp' ? 'white' : '#25D366',
                                    '&:hover': {
                                        backgroundColor: shareMethod === 'whatsapp' ? '#20b85a' : 'rgba(37, 211, 102, 0.08)',
                                    }
                                }}
                            >
                                WhatsApp (sin número)
                            </Button>
                        </Grid>

                        <Grid item xs={12}>
                            <Button
                                fullWidth
                                variant={shareMethod === 'whatsapp_number' ? 'contained' : 'outlined'}
                                startIcon={<img src="https://cdn.jsdelivr.net/npm/simple-icons@v8/icons/whatsapp.svg" width="24" height="24" alt="WhatsApp" />}
                                onClick={() => setShareMethod('whatsapp_number')}
                                sx={{
                                    justifyContent: 'flex-start',
                                    backgroundColor: shareMethod === 'whatsapp_number' ? '#25D366' : 'transparent',
                                    borderColor: '#25D366',
                                    color: shareMethod === 'whatsapp_number' ? 'white' : '#25D366',
                                    '&:hover': {
                                        backgroundColor: shareMethod === 'whatsapp_number' ? '#20b85a' : 'rgba(37, 211, 102, 0.08)',
                                    }
                                }}
                            >
                                WhatsApp (con número específico)
                            </Button>
                        </Grid>

                        <Grid item xs={12}>
                            <Button
                                fullWidth
                                variant={shareMethod === 'instagram' ? 'contained' : 'outlined'}
                                startIcon={<img src="https://cdn.jsdelivr.net/npm/simple-icons@v8/icons/instagram.svg" width="24" height="24" alt="Instagram" />}
                                onClick={() => setShareMethod('instagram')}
                                sx={{
                                    justifyContent: 'flex-start',
                                    backgroundColor: shareMethod === 'instagram' ? '#E4405F' : 'transparent',
                                    borderColor: '#E4405F',
                                    color: shareMethod === 'instagram' ? 'white' : '#E4405F',
                                    '&:hover': {
                                        backgroundColor: shareMethod === 'instagram' ? '#d73d5a' : 'rgba(228, 64, 95, 0.08)',
                                    }
                                }}
                            >
                                Instagram (copia texto y abre app)
                            </Button>
                        </Grid>

                        <Grid item xs={12}>
                            <Button
                                fullWidth
                                variant={shareMethod === 'image' ? 'contained' : 'outlined'}
                                startIcon={<DownloadIcon />}
                                onClick={() => setShareMethod('image')}
                                sx={{
                                    justifyContent: 'flex-start',
                                    backgroundColor: shareMethod === 'image' ? '#7c3aed' : 'transparent',
                                    borderColor: '#7c3aed',
                                    color: shareMethod === 'image' ? 'white' : '#7c3aed',
                                    '&:hover': {
                                        backgroundColor: shareMethod === 'image' ? '#6d28d9' : 'rgba(124, 58, 237, 0.08)',
                                    }
                                }}
                            >
                                Descargar/Compartir como imagen
                            </Button>
                        </Grid>
                    </Grid>
                </DialogContent>
                <DialogActions sx={{ p: 2 }}>
                    <Button onClick={() => setOpenShareDialog(false)}>Cancelar</Button>
                    <Button
                        variant="contained"
                        onClick={ejecutarCompartir}
                        sx={{ backgroundColor: '#7c3aed', '&:hover': { backgroundColor: '#6d28d9' } }}
                    >
                        Compartir
                    </Button>
                </DialogActions>
            </Dialog>

            {/* FAB para agregar rápido en móvil */}
            {isMobile && (
                <Fab
                    color="primary"
                    sx={{
                        position: 'fixed',
                        bottom: 90,
                        right: 16,
                        backgroundColor: '#7c3aed',
                        '&:hover': { backgroundColor: '#6d28d9' }
                    }}
                    onClick={() => {
                        resetNewFormula();
                        setOpenDialog(true);
                    }}
                >
                    <AddIcon />
                </Fab>
            )}
        </Box>
    );
};

export default FormulasCeramicas;