import React from "react";
import { Routes, Route, HashRouter } from 'react-router-dom';
import { ThemeContextProvider } from './ThemeContext';
import App from "./App";
import VentaVarios from './VentaVarios';
import Alumnos from './Alumnos';
import EstadisticasGanancias from "./EstadisticasGanancias";
import FormulasCeramicas from "./FormulasCeramicas";

const Router = () => (
    <ThemeContextProvider>
        <HashRouter>
            <Routes>
                <Route path="/" element={<App />}>
                    <Route index element={<Alumnos />} />
                    <Route path="Alumnos" element={<Alumnos />} />
                    <Route path="formulas" element={<FormulasCeramicas />} />
                    <Route path="VentaVarios" element={<VentaVarios />} />
                    <Route path="Estadisticas" element={<EstadisticasGanancias />} />
                </Route>
            </Routes>
        </HashRouter>
    </ThemeContextProvider>
);

export default Router;