import React, { createContext, useContext, useState, useMemo } from 'react';
import { createTheme } from '@mui/material/styles';

const ThemeContext = createContext();

export const useThemeContext = () => {
    const context = useContext(ThemeContext);
    if (!context) {
        throw new Error('useThemeContext must be used within ThemeProvider');
    }
    return context;
};

export const ThemeContextProvider = ({ children }) => {
    // Forzar modo claro siempre
    const actualTheme = 'light';

    // Tema claro con colores violáceos, naranjas y azules
    const theme = useMemo(() => createTheme({
        palette: {
            mode: 'light', // FORZADO a claro
            primary: {
                main: '#7c3aed',
                light: '#a78bfa',
                dark: '#5b21b6',
            },
            secondary: {
                main: '#ea580c',
                light: '#f97316',
                dark: '#c2410c',
            },
            accent: {
                main: '#3b82f6',
                light: '#60a5fa',
                dark: '#2563eb',
            },
            background: {
                default: '#f8fafc',
                paper: '#ffffff',
            },
            text: {
                primary: '#1e293b',
                secondary: '#64748b',
            },
        },
        components: {
            MuiButton: {
                styleOverrides: {
                    root: {
                        borderRadius: '40px',
                        textTransform: 'none',
                        fontWeight: 600,
                    },
                },
            },
            MuiCard: {
                styleOverrides: {
                    root: {
                        borderRadius: '16px',
                        transition: 'all 0.3s ease',
                        '&:hover': {
                            transform: 'translateY(-2px)',
                            boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)',
                        },
                    },
                },
            },
            MuiPaper: {
                styleOverrides: {
                    root: {
                        backgroundImage: 'none',
                    },
                },
            },
        },
    }), []); // Sin dependencias porque no cambia

    const value = useMemo(() => ({
        actualTheme,
        theme,
    }), [actualTheme, theme]);

    return (
        <ThemeContext.Provider value={value}>
            {children}
        </ThemeContext.Provider>
    );
};