import React from 'react';
import { Grid, Card, CardContent, Typography, Box, useMediaQuery } from '@mui/material';
import { useTheme } from '@mui/material/styles';

const KPICards = ({ alumnosActivos, totalGanancias, alumnosPendientes }) => {
    const theme = useTheme();
    const isSmallMobile = useMediaQuery('(max-width:450px)');
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

    const cards = [
        {
            title: 'Alumnos Activos',
            value: alumnosActivos,
            icon: '👥',
            color: '#6366f1',
        },
        {
            title: 'Ganancias del Mes',
            value: `$${totalGanancias.toLocaleString()}`,
            icon: '💰',
            color: '#10b981',
        },
        {
            title: 'Pagos Pendientes',
            value: alumnosPendientes,
            icon: '⚠️',
            color: '#f59e0b',
        },
    ];

    return (
        <Grid
            container
            spacing={isSmallMobile ? 0.5 : 1.5}
            sx={{ mb: isSmallMobile ? 1 : 2 }}
        >
            {cards.map((card, index) => (
                <Grid
                    item
                    xs={isSmallMobile ? 4 : 12}
                    sm={4}
                    key={index}
                    sx={{
                        animation: 'fadeInUp 0.5s ease forwards',
                        animationDelay: `${index * 0.1}s`,
                        opacity: 0,
                        '@keyframes fadeInUp': {
                            '0%': {
                                opacity: 0,
                                transform: 'translateY(20px)'
                            },
                            '100%': {
                                opacity: 1,
                                transform: 'translateY(0)'
                            }
                        }
                    }}
                >
                    <Card
                        elevation={isSmallMobile ? 1 : 0}
                        sx={{
                            background: isSmallMobile
                                ? '#ffffff'
                                : 'rgba(255,255,255,0.05)',
                            border: isSmallMobile
                                ? '1px solid #e2e8f0'
                                : '1px solid rgba(255,255,255,0.1)',
                            borderRadius: isSmallMobile ? 1 : 1.5,
                            height: '100%',
                            minHeight: isSmallMobile ? '55px' : 'auto',
                            transition: 'all 0.2s ease',
                            '&:hover': isSmallMobile ? {
                                transform: 'translateY(-1px)',
                                boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
                            } : {},
                        }}
                    >
                        <CardContent sx={{
                            p: isSmallMobile ? '8px 8px' : 1.5,
                            '&:last-child': {
                                pb: isSmallMobile ? '8px' : 1.5
                            }
                        }}>
                            <Box sx={{
                                display: 'flex',
                                flexDirection: isSmallMobile ? 'column' : 'row',
                                alignItems: 'center',
                                justifyContent: 'center',
                                gap: isSmallMobile ? 0.5 : 1.5,
                                textAlign: isSmallMobile ? 'center' : 'left',
                            }}>
                                <Typography sx={{
                                    fontSize: isSmallMobile ? '0.9rem' : '1.5rem',
                                    lineHeight: 1,
                                    mb: isSmallMobile ? 0.5 : 0,
                                }}>
                                    {card.icon}
                                </Typography>
                                <Box sx={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    alignItems: isSmallMobile ? 'center' : 'flex-start',
                                    width: '100%',
                                    gap: isSmallMobile ? 0.25 : 0.5,
                                }}>
                                    <Typography
                                        variant="caption"
                                        sx={{
                                            fontSize: isSmallMobile ? '0.45rem' : '0.65rem',
                                            color: '#1e293b', // Negro en lugar de gris
                                            fontWeight: 600,
                                            textTransform: 'uppercase',
                                            letterSpacing: '0.5px',
                                            lineHeight: 1.3,
                                        }}
                                    >
                                        {card.title}
                                    </Typography>
                                    <Typography
                                        sx={{
                                            fontSize: isSmallMobile ? '0.7rem' : '1.1rem',
                                            fontWeight: 'bold',
                                            color: card.color,
                                            lineHeight: 1.3,
                                            whiteSpace: 'nowrap',
                                            overflow: 'hidden',
                                            textOverflow: 'ellipsis',
                                            maxWidth: '100%',
                                        }}
                                    >
                                        {card.value}
                                    </Typography>
                                </Box>
                            </Box>
                        </CardContent>
                    </Card>
                </Grid>
            ))}
        </Grid>
    );
};

export default KPICards;